// ArkNetzWebWeaver — protocol mail crypto (Phase 1, X25519 wrap since fix round 2).
// Thread turn 18: hybrid envelope like PGP/GPG and Signal groups.
// Compress + encrypt once with a random AES-256-GCM key, wrap only the
// 32-byte key per recipient. No new dependency: Web Crypto only, plus
// the existing Zstd helper (src/lib/zstd.ts) for compression.
//
// KEY-WRAP SCHEME (documented exactly, as the brief requires):
//   - Per user: X25519 (Curve25519 Diffie-Hellman). Generated by
//     generateMailKeypair(); the public key is published in the
//     contacts directory as a JWK (kty "OKP", crv "X25519", 32-byte
//     "x"), the private key never leaves the device. This REPLACED
//     RSA-OAEP-2048 in fix round 2 (item 4): RSA wrapped keys were
//     256 bytes and published RSA JWKs ~427 bytes of JSON, giving
//     ~467 MiB per 1M contacts; X25519 restores the thread's figures
//     (see sizes below). No envelopes existed in the wild when the
//     switch was made (nothing shipped, no central repos), so no
//     migration was needed; MAIL_PROTOCOL_VERSION stays "arknetz-mail/1".
//   - Per message: a fresh AES-256-GCM key (32 random bytes, the
//     "content-encryption key", CEK) + a fresh 12-byte IV. The
//     Zstd-compressed plaintext is encrypted with it, ONCE, for all
//     recipients — so the CEK must be conveyed to each recipient,
//     which is what the wrap below does. (A KEM-DEM that derives a
//     different key per recipient would need a different ciphertext
//     per recipient and would defeat encrypt-once; that is why a
//     wrap of the shared CEK is used instead of a bare KDF.)
//   - Per recipient, a FRESH ephemeral X25519 keypair is generated
//     (one encapsulation per recipient — no ephemeral reuse across
//     recipients, so no cross-recipient reuse assumption is needed):
//       shared = X25519(ephemeralPriv, recipientPub)   [32 bytes]
//       KEK    = HKDF-SHA-256(shared, salt = ephemeralPubRaw,
//                              info = "arknetz-mail/1 key-wrap:<fingerprint>")
//       wrapped = AES-KW(KEK, CEK)                      [40 bytes]
//     The salt binds the KEK to this encapsulation; the info binds it
//     to the recipient (fingerprint = first 32 hex chars of
//     SHA-256(lowercased address)) and to this protocol version, so a
//     wrapped key cannot be transplanted to another recipient or
//     another protocol version. AES-KW (RFC 3394) is an authenticated
//     wrap: a tampered wrapped key fails on unwrap, it never yields a
//     wrong CEK. The shared secret is rejected if it is all zeros.
//   - A wrapped-key entry is therefore 32 (ephemeral public key) +
//     40 (AES-KW output) = 72 bytes raw. The thread's "~64 bytes"
//     estimate is 8 bytes short because it did not count AES-KW's
//     8-byte integrity check value (32-byte CEK + 8 = 40); 72 bytes
//     is the sound minimum for an authenticated wrap of a 256-bit
//     key with a 32-byte ephemeral key. Measured, not estimated:
//     b64decode(wrappedKeyB64).length is 40 and
//     b64decode(ephemeralPublicKeyB64).length is 32 for every entry.
//   - Wrapped keys are indexed by fingerprint (see above), so BCC
//     addresses never appear in cleartext in the envelope.
//   - ENGINE FLOOR: the standard `{ name: "X25519" }` Web Crypto
//     form is used (NOT the old `{ name: "ECDH", namedCurve:
//     "X25519" }` form — Node rejects that with "Unrecognized
//     namedCurve" and pre-133 Chromium lacks it). Verified working
//     in this repo on Node v24.22.1; browsers need X25519 Web Crypto
//     (Chrome/Edge 133+, Firefox 130+, Safari 17+). The old
//     Node-only "NODE-X25519" curve name was deliberately NOT used:
//     it does not exist in browsers, so code written against it
//     would pass Node tests and break in the Tauri WebView.
//
// SIZES (measured from real keys generated by generateMailKeypair;
// see tests/mail.test.ts, which asserts the invariant ones):
//   - wrapped-key entry: 72 bytes raw (32 ephemeral + 40 AES-KW)
//   - public key: 32 bytes raw; public JWK JSON 102 bytes
//     ({"kty":"OKP","crv":"X25519","x":"<43 chars>",...})
//   - contacts entry JSON: 165 bytes for a minimal entry
//     (address + JWK + updatedAt) -> 157.4 MiB per 1M users
//     uncompressed JSON; the raw keys alone are 32 bytes/user
//     (32 MB per 1M). The thread's "~40 MB per 1M" assumed ~40
//     bytes/entry, i.e. raw binary packing (32-byte key + short
//     address), not JSON framing — the JSON shard shape keeps the
//     directory above that figure uncompressed, BUT the shards are
//     stored Zstd-compressed (contacts.json.zst), and measured on
//     2,000 real entries the compressed shard is 37.0 bytes/entry,
//     i.e. ~35.3 MiB per 1M in the stored form — so the thread's
//     ~40 MB figure holds for the stored .json.zst form. The
//     key-encoding figure itself (32-byte public keys) is restored
//     exactly.
// All functions are pure over their inputs (no network, no storage),
// so they are testable in Node with the built-in Web Crypto.

import { compressBytes, decompressBytes } from "../zstd.js";
import {
  MAIL_PROTOCOL_VERSION,
  type EncryptedMailEnvelope,
  type MailAddress,
  type MailKeypair,
  type MailPlaintext,
  type WrappedKeyEntry,
} from "./types.js";

/** Raw byte size of one wrapped-key entry: 32-byte ephemeral X25519
 *  public key + 40-byte AES-KW-wrapped 256-bit CEK. */
export const WRAPPED_KEY_ENTRY_BYTES = 72;
/** Raw byte size of the AES-KW-wrapped CEK alone (32-byte key + the
 *  8-byte RFC 3394 integrity check value). */
export const AES_KW_WRAPPED_KEY_BYTES = 40;
/** Raw byte size of an X25519 public key. */
export const X25519_PUBLIC_KEY_BYTES = 32;

export function b64encode(bytes: Uint8Array): string {
  let binary = "";
  const CHUNK = 0x8000;
  for (let i = 0; i < bytes.length; i += CHUNK) {
    binary += String.fromCharCode(...bytes.subarray(i, i + CHUNK));
  }
  return btoa(binary);
}

export function b64decode(b64: string): Uint8Array {
  const binary = atob(b64);
  const out = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) out[i] = binary.charCodeAt(i);
  return out;
}

export function randomHex(bytes = 16): string {
  const b = new Uint8Array(bytes);
  crypto.getRandomValues(b);
  return [...b].map((x) => x.toString(16).padStart(2, "0")).join("");
}

export function newMessageId(): string {
  return `mail-${randomHex(16)}`;
}

export function newThreadId(): string {
  return `thread-${randomHex(16)}`;
}

/** SHA-256 hex of the lowercased address; the fingerprint is its first
 *  32 hex chars (128 bits — collision-free for any realistic inbox). */
export async function addressFingerprint(address: MailAddress): Promise<string> {
  const digest = await crypto.subtle.digest(
    "SHA-256",
    new TextEncoder().encode(address.toLowerCase()),
  );
  return [...new Uint8Array(digest)]
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("")
    .slice(0, 32);
}

/** Generate a per-user mail keypair (X25519). The private key is
 *  extractable here so the app can store it encrypted in IndexedDB
 *  (see ia-media.ts for the passphrase-encryption pattern); it must
 *  NEVER be exported in cleartext or sent anywhere. */
export async function generateMailKeypair(address: MailAddress): Promise<MailKeypair> {
  // TS 5.9's lib.dom has no X25519 generateKey overload (only
  // Ed25519), so the call types as CryptoKey | CryptoKeyPair; at
  // runtime X25519 always generates a pair.
  const pair = (await crypto.subtle.generateKey(
    { name: "X25519" },
    true,
    ["deriveBits"],
  )) as CryptoKeyPair;
  const publicKeyJwk = await crypto.subtle.exportKey("jwk", pair.publicKey);
  return { address, publicKey: pair.publicKey, privateKey: pair.privateKey, publicKeyJwk };
}

/** Import a published X25519 public key from its contacts-directory
 *  JWK (kty "OKP", crv "X25519"). */
export async function importPublicKey(jwk: JsonWebKey): Promise<CryptoKey> {
  if (jwk.kty !== "OKP" || jwk.crv !== "X25519" || typeof jwk.x !== "string") {
    throw new Error(
      "public key JWK is not an X25519 key (expected kty \"OKP\", crv \"X25519\")",
    );
  }
  return crypto.subtle.importKey("jwk", jwk, { name: "X25519" }, true, []);
}

/** Import a private X25519 key from an exported JWK (e.g. restored
 *  from encrypted local storage). */
export async function importPrivateKey(jwk: JsonWebKey): Promise<CryptoKey> {
  if (jwk.kty !== "OKP" || jwk.crv !== "X25519" || typeof jwk.d !== "string") {
    throw new Error(
      "private key JWK is not an X25519 key (expected kty \"OKP\", crv \"X25519\")",
    );
  }
  return crypto.subtle.importKey("jwk", jwk, { name: "X25519" }, true, ["deriveBits"]);
}

/** X25519 key-agreement params for deriveBits. Written as a helper
 *  because TS 5.9's lib.dom types the derive params as
 *  EcdhKeyDeriveParams (an Algorithm with a `public` key) — the
 *  `{ name: "X25519", public }` object satisfies that shape at
 *  runtime, and the cast below is only a type-level bridge. */
function x25519DeriveParams(publicKey: CryptoKey): EcdhKeyDeriveParams {
  return { name: "X25519", public: publicKey } as unknown as EcdhKeyDeriveParams;
}

/** Reject an all-zero X25519 shared secret (invalid / low-order peer
 *  public key). Web Crypto implementations are expected to do this
 *  themselves, but the check is cheap and the failure mode of
 *  accepting it — a predictable KEK — is catastrophic, so it is
 *  enforced here on both the seal and the open path. */
function assertNonZeroSharedSecret(shared: ArrayBuffer): void {
  const bytes = new Uint8Array(shared);
  let allZero = true;
  for (const b of bytes) {
    if (b !== 0) {
      allZero = false;
      break;
    }
  }
  if (allZero) {
    throw new Error("X25519 shared secret is all zeros — refusing (invalid public key)");
  }
}

/** Derive the AES-KW key-encryption key for one recipient from one
 *  encapsulation: HKDF-SHA-256 over the X25519 shared secret, salted
 *  with the ephemeral public key (binds the KEK to this encapsulation)
 *  and info-bound to this protocol version and this recipient's
 *  fingerprint (binds it to this recipient). `ownPrivateKey` is the
 *  side doing the agreement (the ephemeral private key when sealing,
 *  the recipient's long-term private key when opening);
 *  `peerPublicKey` is the other side's public key. */
async function deriveWrapKey(
  ownPrivateKey: CryptoKey,
  peerPublicKey: CryptoKey,
  ephemeralPublicRaw: Uint8Array,
  fingerprint: string,
): Promise<CryptoKey> {
  const shared = await crypto.subtle.deriveBits(
    x25519DeriveParams(peerPublicKey),
    ownPrivateKey,
    256,
  );
  assertNonZeroSharedSecret(shared);
  const hkdfKey = await crypto.subtle.importKey(
    "raw",
    shared,
    { name: "HKDF" },
    false,
    ["deriveKey"],
  );
  return crypto.subtle.deriveKey(
    {
      name: "HKDF",
      hash: "SHA-256",
      salt: ephemeralPublicRaw as BufferSource,
      info: new TextEncoder().encode(`arknetz-mail/1 key-wrap:${fingerprint}`),
    },
    hkdfKey,
    { name: "AES-KW", length: 256 },
    false,
    ["wrapKey", "unwrapKey"],
  );
}

/** Wrap one content-encryption key for one recipient (see the header
 *  for the exact construction). Returns the entry that goes in the
 *  envelope: fingerprint + 40-byte AES-KW blob + 32-byte ephemeral
 *  public key, all base64. */
export async function wrapContentKey(
  aesKey: CryptoKey,
  recipientPublicKey: CryptoKey,
  recipientAddress: MailAddress,
): Promise<WrappedKeyEntry> {
  const fingerprint = await addressFingerprint(recipientAddress);
  const ephemeral = (await crypto.subtle.generateKey(
    { name: "X25519" },
    true,
    ["deriveBits"],
  )) as CryptoKeyPair;
  const ephemeralRaw = new Uint8Array(
    await crypto.subtle.exportKey("raw", ephemeral.publicKey),
  );
  if (ephemeralRaw.length !== X25519_PUBLIC_KEY_BYTES) {
    throw new Error("ephemeral X25519 public key is not 32 bytes — refusing to wrap");
  }
  const kek = await deriveWrapKey(
    ephemeral.privateKey,
    recipientPublicKey,
    ephemeralRaw,
    fingerprint,
  );
  const wrapped = await crypto.subtle.wrapKey("raw", aesKey, kek, { name: "AES-KW" });
  const wrappedBytes = new Uint8Array(wrapped);
  if (wrappedBytes.length !== AES_KW_WRAPPED_KEY_BYTES) {
    throw new Error("AES-KW-wrapped key is not 40 bytes — refusing to wrap");
  }
  return {
    fingerprint,
    wrappedKeyB64: b64encode(wrappedBytes),
    ephemeralPublicKeyB64: b64encode(ephemeralRaw),
  };
}

/** Unwrap one wrapped content-encryption key with the recipient's
 *  long-term X25519 private key. Throws with a plain message when the
 *  entry is malformed, is not for this recipient, or does not unwrap
 *  (wrong private key or tampered wrap) — never a partial key. */
export async function unwrapContentKey(
  entry: WrappedKeyEntry,
  recipientAddress: MailAddress,
  recipientPrivateKey: CryptoKey,
): Promise<CryptoKey> {
  const fingerprint = await addressFingerprint(recipientAddress);
  if (entry.fingerprint !== fingerprint) {
    throw new Error("wrapped key is not addressed to this recipient");
  }
  const ephemeralRaw = b64decode(entry.ephemeralPublicKeyB64);
  if (ephemeralRaw.length !== X25519_PUBLIC_KEY_BYTES) {
    throw new Error("wrapped key has a malformed ephemeral public key (expected 32 bytes)");
  }
  const wrappedBytes = b64decode(entry.wrappedKeyB64);
  if (wrappedBytes.length !== AES_KW_WRAPPED_KEY_BYTES) {
    throw new Error("wrapped key is malformed (expected a 40-byte AES-KW blob)");
  }
  const ephemeralPublic = await crypto.subtle.importKey(
    "raw",
    ephemeralRaw as BufferSource,
    { name: "X25519" },
    false,
    [],
  );
  const kek = await deriveWrapKey(
    recipientPrivateKey,
    ephemeralPublic,
    ephemeralRaw,
    fingerprint,
  );
  try {
    return await crypto.subtle.unwrapKey(
      "raw",
      wrappedBytes as BufferSource,
      kek,
      { name: "AES-KW" },
      { name: "AES-GCM", length: 256 },
      false,
      ["decrypt"],
    );
  } catch {
    throw new Error("wrapped key does not unwrap with this private key");
  }
}

/** Seal arbitrary bytes for one recipient: fresh AES-256-GCM key +
 *  IV, X25519-wrapped key (see header). This is the shared primitive
 *  under both mail envelopes and team-key sharing (team-inbox.ts). */
export async function sealBytesForRecipient(
  data: Uint8Array,
  recipientPublicKey: CryptoKey,
  recipientAddress: MailAddress,
): Promise<{ ivB64: string; ciphertextB64: string; wrappedKey: WrappedKeyEntry }> {
  const aesKey = await crypto.subtle.generateKey(
    { name: "AES-GCM", length: 256 },
    true,
    ["encrypt", "decrypt"],
  );
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const cipher = await crypto.subtle.encrypt(
    { name: "AES-GCM", iv: iv as BufferSource },
    aesKey,
    data as BufferSource,
  );
  return {
    ivB64: b64encode(iv),
    ciphertextB64: b64encode(new Uint8Array(cipher)),
    wrappedKey: await wrapContentKey(aesKey, recipientPublicKey, recipientAddress),
  };
}

/** Open bytes sealed with sealBytesForRecipient. Throws if the wrapped
 *  key is not for this recipient or the ciphertext was tampered with
 *  (AES-GCM authentication fails). */
export async function openSealedBytes(
  sealed: { ivB64: string; ciphertextB64: string; wrappedKey: WrappedKeyEntry },
  recipientAddress: MailAddress,
  recipientPrivateKey: CryptoKey,
): Promise<Uint8Array> {
  const fingerprint = await addressFingerprint(recipientAddress);
  if (sealed.wrappedKey.fingerprint !== fingerprint) {
    throw new Error("sealed payload is not addressed to this recipient");
  }
  const aesKey = await unwrapContentKey(sealed.wrappedKey, recipientAddress, recipientPrivateKey);
  const plain = await crypto.subtle.decrypt(
    { name: "AES-GCM", iv: b64decode(sealed.ivB64) as BufferSource },
    aesKey,
    b64decode(sealed.ciphertextB64) as BufferSource,
  );
  return new Uint8Array(plain);
}

/** One recipient for envelope encryption: address + already-imported
 *  public key (import with importPublicKey from a contacts JWK). */
export interface EnvelopeRecipient {
  address: MailAddress;
  publicKey: CryptoKey;
}

function serialisePlaintext(plain: MailPlaintext): Uint8Array {
  // Attachments ride inside the payload as base64; the whole payload
  // is then Zstd-compressed, so attachments are compressed, and the
  // AES-GCM layer encrypts them.
  const wire = {
    ...plain,
    attachments: plain.attachments.map((a) => ({
      filename: a.filename,
      mime: a.mime,
      dataB64: b64encode(a.data),
    })),
  };
  return new TextEncoder().encode(JSON.stringify(wire));
}

function parsePlaintext(bytes: Uint8Array): MailPlaintext {
  const raw = JSON.parse(new TextDecoder().decode(bytes)) as Record<string, unknown>;
  if (raw.version !== MAIL_PROTOCOL_VERSION) {
    throw new Error(`unsupported mail version: ${String(raw.version)}`);
  }
  const attachments = Array.isArray(raw.attachments)
    ? (raw.attachments as Array<Record<string, unknown>>).map((a) => ({
        filename: String(a.filename ?? ""),
        mime: String(a.mime ?? "application/octet-stream"),
        data: b64decode(String(a.dataB64 ?? "")),
      }))
    : [];
  return {
    version: MAIL_PROTOCOL_VERSION,
    messageId: String(raw.messageId ?? ""),
    threadId: String(raw.threadId ?? ""),
    from: String(raw.from ?? ""),
    to: Array.isArray(raw.to) ? (raw.to as string[]) : [],
    cc: Array.isArray(raw.cc) ? (raw.cc as string[]) : [],
    subject: String(raw.subject ?? ""),
    body: String(raw.body ?? ""),
    sentAt: typeof raw.sentAt === "number" ? raw.sentAt : 0,
    attachments,
  };
}

/** Seal a message: compress + encrypt once, wrap the AES key per
 *  recipient (fresh ephemeral X25519 encapsulation per recipient —
 *  see the header). `recipients` must include EVERYONE who may open
 *  it — To + CC + BCC. BCC addresses are passed here (so they get a
 *  wrapped key) but must NOT appear in `plain.to` / `plain.cc` —
 *  callers build the plaintext with BCC already stripped (compose.ts
 *  does this). The caller is responsible for that split; sealMail
 *  asserts it by refusing any recipient that appears in neither
 *  to/cc nor the explicit `bcc` list. */
export async function sealMail(
  plain: MailPlaintext,
  recipients: EnvelopeRecipient[],
  bcc: MailAddress[] = [],
): Promise<EncryptedMailEnvelope> {
  if (recipients.length === 0) throw new Error("cannot seal mail with no recipients");
  const publicRecipients = new Set([...plain.to, ...plain.cc].map((a) => a.toLowerCase()));
  for (const r of recipients) {
    const lower = r.address.toLowerCase();
    if (!publicRecipients.has(lower) && !bcc.some((b) => b.toLowerCase() === lower)) {
      throw new Error(
        `recipient ${r.address} is in neither To/CC nor BCC — refusing to seal (would leak addressing)`,
      );
    }
  }
  const compressed = await compressBytes(serialisePlaintext(plain));
  const aesKey = await crypto.subtle.generateKey(
    { name: "AES-GCM", length: 256 },
    true,
    ["encrypt", "decrypt"],
  );
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const cipher = await crypto.subtle.encrypt(
    { name: "AES-GCM", iv: iv as BufferSource },
    aesKey,
    compressed as BufferSource,
  );
  const wrappedKeys: WrappedKeyEntry[] = [];
  for (const r of recipients) {
    wrappedKeys.push(await wrapContentKey(aesKey, r.publicKey, r.address));
  }
  return {
    version: MAIL_PROTOCOL_VERSION,
    messageId: plain.messageId,
    threadId: plain.threadId,
    from: plain.from,
    recipients: [...plain.to, ...plain.cc],
    sentAt: plain.sentAt,
    ivB64: b64encode(iv),
    ciphertextB64: b64encode(new Uint8Array(cipher)),
    wrappedKeys,
    compressedBytes: compressed.length,
  };
}

/** Open a sealed envelope for one recipient. Finds that recipient's
 *  wrapped key by fingerprint, unwraps the AES key, AES-GCM-decrypts,
 *  Zstd-decompresses, parses. Throws (with a plain message) when the
 *  recipient has no wrapped key, the key does not unwrap, or the
 *  ciphertext fails authentication — all three mean "not for you, or
 *  tampered with", never a partial plaintext. */
export async function openMail(
  envelope: EncryptedMailEnvelope,
  recipientAddress: MailAddress,
  recipientPrivateKey: CryptoKey,
): Promise<MailPlaintext> {
  if (envelope.version !== MAIL_PROTOCOL_VERSION) {
    throw new Error(`unsupported mail version: ${envelope.version}`);
  }
  const fingerprint = await addressFingerprint(recipientAddress);
  const entry = envelope.wrappedKeys.find((w) => w.fingerprint === fingerprint);
  if (!entry) {
    throw new Error(`no wrapped key for ${recipientAddress} in this envelope`);
  }
  let aesKey: CryptoKey;
  try {
    aesKey = await unwrapContentKey(entry, recipientAddress, recipientPrivateKey);
  } catch (err) {
    if (err instanceof Error && err.message === "wrapped key is not addressed to this recipient") {
      throw err;
    }
    throw new Error("wrapped key does not unwrap with this private key");
  }
  let compressed: Uint8Array;
  try {
    const plain = await crypto.subtle.decrypt(
      { name: "AES-GCM", iv: b64decode(envelope.ivB64) as BufferSource },
      aesKey,
      b64decode(envelope.ciphertextB64) as BufferSource,
    );
    compressed = new Uint8Array(plain);
  } catch {
    throw new Error("mail ciphertext failed authentication — tampered with or wrong key");
  }
  const bytes = await decompressBytes(compressed);
  const mail = parsePlaintext(bytes);
  if (mail.messageId !== envelope.messageId || mail.threadId !== envelope.threadId) {
    throw new Error("decrypted mail header does not match the envelope — refusing it");
  }
  return mail;
}
